patches.new_text:
if velocity.length_squared() > 0.0:
				last_move_direction = velocity.normalized()

if Input.is_action_just_pressed("dash") and dash_cooldown <= 0.0:
				var dash_direction = velocity.normalized()
				if dash_direction == Vector2.ZERO:
								dash_direction = last_move_direction
				apply_central_impulse(dash_direction * Constants.DASH_AMOUNT)
				Globals.play_sound_effect($DashSound.stream)
				dash_cooldown = 0.75
